(async()=>{'use strict';const $=s=>document.querySelector(s),KEY='spotsense-models-v1';let d={math:{attempts:0,correct:0},mix:{}};try{const v=JSON.parse(SSStorage.get(KEY)||'null');if(v?.math&&v?.mix)d=v}catch{}const save=()=>SSStorage.set(KEY,JSON.stringify(d)),fmt=n=>Number(n.toFixed(2)).toLocaleString();let questions=[],index=0,answered=false;function stats(){$('#q-stats').textContent=`模型題答對 ${d.math.correct}/${d.math.attempts}；與範圍動作辨識率分開。`}function draw(){answered=false;const q=questions[index];$('#q-progress').textContent=`第${index+1}/${questions.length}題`;$('#q-title').textContent=q.title;$('#q-prompt').textContent=q.prompt;$('#q-bound').textContent='模型邊界：'+q.assumptions;$('#q-options').replaceChildren();$('#q-feedback').hidden=true;for(const v of q.options){const b=document.createElement('button');b.className='ss-link ss-choice';b.textContent=fmt(v)+' '+q.unit;b.onclick=()=>{if(answered)return;answered=true;const ok=Math.abs(v-q.answer)<.001;d.math.attempts++;if(ok)d.math.correct++;save();$('#q-feedback').hidden=false;$('#q-feedback').textContent=(ok?'答對了。':'這次未答對。')+'答案：'+fmt(q.answer)+' '+q.unit+'\n'+q.formula+'\n來源：'+q.source;$('#q-options').querySelectorAll('button').forEach(e=>e.disabled=true);stats()};$('#q-options').append(b)}stats()}$('#q-next').onclick=()=>{index=(index+1)%questions.length;draw()};function mix(){const t=+$('#frequency-preset').value;d.mix[t]??={raise:0,fold:0,samples:[]};const m=d.mix[t],n=m.raise+m.fold;$('#mix-report').replaceChildren();const p=document.createElement('p');p.textContent=`手動 ${n}/100 次；Raise ${m.raise}／Fold ${m.fold}。`+(n?`實際Raise ${(m.raise/n*100).toFixed(1)}%，與目標差 ${(m.raise/n*100-t).toFixed(1)} 個百分點。`:'');$('#mix-report').append(p);if(m.samples.length){const s=document.createElement('p');s.textContent=`獨立抽籤示範：Raise ${m.samples.at(-1).raise}/100（不加入手動紀錄）`;$('#mix-report').append(s)}$('#mix-raise').disabled=$('#mix-fold').disabled=n>=100;save()}for(const a of ['raise','fold'])$('#mix-'+a).onclick=()=>{const m=d.mix[$('#frequency-preset').value];if(m.raise+m.fold<100){m[a]++;mix()}};$('#frequency-preset').onchange=mix;$('#mix-sample').onclick=()=>{const t=+$('#frequency-preset').value,vs=new Uint32Array(100);crypto.getRandomValues(vs);const r=[...vs].filter(v=>v/4294967296<t/100).length,m=d.mix[t];m.samples.push({raise:r,at:new Date().toISOString()});m.samples=m.samples.slice(-10);mix()};$('#mix-new').onclick=()=>{const m=d.mix[$('#frequency-preset').value];if(m.raise+m.fold&&!confirm('清除目前手動次數，開始新一組？'))return;m.raise=m.fold=0;mix()};function tab(mode){for(const n of ['math','frequency']){$('#'+n).hidden=n!==mode;$('#tab-'+n).setAttribute('aria-pressed',String(n===mode));$('#tab-'+n).classList.toggle('ss-primary',n===mode)}}$('#tab-math').onclick=()=>tab('math');$('#tab-frequency').onclick=()=>tab('frequency');mix();try{const r=await fetch('model-questions.json');if(!r.ok)throw Error();questions=await r.json();draw()}catch{$('#q-prompt').textContent='題庫載入失敗；請透過網站網址開啟，確認model-questions.json已部署。';$('#q-next').disabled=true}})();